        raise TypeError("duration must be a number")
    if duration < 0:
        raise ValueError("duration must be non-negative")
    r_script_path = os.path.abspath(r_script_path)
    output_path = os.path.abspath(output_path)
    try:
        proc = subprocess.Popen(["Rscript", r_script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except Exception:
        return False, 'File not generated within the specified duration.'
    start_time = time.time()
    interval = 0.5
    while time.time() - start_time <= duration:
        matches = glob.glob(output_path)
        if matches:
            if proc.poll() is None:
                try:
                    proc.terminate()
                except Exception:
                    pass
            return True, 'File generated successfully within the specified duration.'
        time.sleep(interval)
    if proc.poll() is None:
        try:
            proc.terminate()
        except Exception:
            pass
    return False, 'File not generated within the specified duration.'

