import subprocess
import psutil
import time
def task_func(process_name: str) -> str:
    if not isinstance(process_name, str) or not process_name.strip():
        raise TypeError("process_name must be a non-empty string")
    process_name = process_name.strip()
    found_processes = []
    for proc in psutil.process_iter(attrs=["name"]):
        try:
            if proc.info.get("name") == process_name:
                found_processes.append(proc)
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            continue
    if not found_processes:
        try:
            subprocess.Popen([process_name])
        except Exception:
            subprocess.Popen(process_name, shell=True)
        time.sleep(0.5)
        return f"Process not found. Starting {process_name}."
    for proc in found_processes:
        try:
            proc.terminate()
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            continue
    gone, alive = psutil.wait_procs(found_processes, timeout=5)
    for proc in alive:
        try:
            proc.kill()
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            continue
    try:
        subprocess.Popen([process_name])
    except Exception:
        subprocess.Popen(process_name, shell=True)
    time.sleep(0.5)
    return f"Process found. Restarting {process_name}."

