import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    src_folder = os.path.abspath(src_folder)
    dst_folder = os.path.abspath(dst_folder)
    if not os.path.isdir(src_folder):
        return {
            'success': False,
            'message': 'Source folder does not exist or is not a directory',
            'failed_files': []
        }
    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder, exist_ok=True)
    files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]
    failed_files = []
    for file_path in files:
        filename = os.path.basename(file_path)
        dst_file = os.path.join(dst_folder, filename + '.gz')
        try:
            with open(dst_file, 'wb') as out_f:
                proc = subprocess.Popen(
                    ['gzip', '-c', file_path],
                    stdout=out_f,
                    stderr=subprocess.PIPE
                )
                _, stderr = proc.communicate()
            if proc.returncode != 0:
                failed_files.append(filename)
                if os.path.exists(dst_file):
                    os.remove(dst_file)
        except Exception:
            failed_files.append(filename)
            if os.path.exists(dst_file):
                os.remove(dst_file)
    if failed_files:
        message = f'Compression completed with failures for {len(failed_files)} file(s)'
        success = False
    else:
        message = 'All files compressed and moved successfully'
        success = True
    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

