                                sy = sy or 0.0
                                ni = ni or 0.0
                                cpu_usage = us + sy + ni
                            break
            except Exception:
                cpu_usage = None
        records.append({"timestamp": now, "cpu_usage": cpu_usage})
        time.sleep(interval)
        if time.time() - start_time >= duration:
            break
    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
    except OSError:
        return None
    return LOGFILE_PATH

