import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not script_path or not os.path.exists(script_path):
        raise OSError("Invalid script path")
    proc = subprocess.Popen(["bash", script_path])
    p = psutil.Process(proc.pid)
    cpu_usage_accumulator = 0.0
    memory_usage_accumulator = 0
    start_time = time.time()
    try:
        while True:
            if not p.is_running() or p.status() == psutil.STATUS_ZOMBIE:
                break
            try:
                cpu = p.cpu_percent(interval=0.1)
                cpu_usage_accumulator += cpu
                mem_info = p.memory_info()
                memory_usage_accumulator += mem_info.rss
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
            if time.time() - start_time >= timeout:
                break
    finally:
        try:
            if p.is_running():
                p.terminate()
                try:
                    p.wait(1)
                except psutil.TimeoutExpired:
                    p.kill()
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            pass
        try:
            proc.wait(timeout=1)
        except Exception:
            pass
    return {"CPU Usage": cpu_usage_accumulator, "Memory Usage": memory_usage_accumulator}

